<script lang="ts">
	import PageLayout from '$components/PageLayout.svelte';
	import { get } from 'svelte/store';
	import { diskSelectionData } from '$lib/store';
	// @ts-expect-error — generated by Wails
	import { LogInfo } from '@wails/runtime/runtime.js';

	interface InstallStep {
		label: string;
	}

	const steps: InstallStep[] = [
		'Formatting disk',
		'Mounting filesystem',
		'Installing base system',
		'Installing kernel',
		'Configuring bootloader',
		'Setting up users',
		'Installing packages',
		'Configuring system',
	];

	let currentStep = $state(0);
	let progress = $state(0);
	let isRunning = $state(false);
	let isComplete = $state(false);
	let elapsedSeconds = $state(0);

	const diskData = $derived(get(diskSelectionData));

	// Countdown timer for elapsed time display
	$effect(() => {
		if (!isRunning) return;

		const interval = setInterval(() => {
			elapsedSeconds++;
		}, 1000);

		return () => clearInterval(interval);
	});

	// Simulate installation steps
	$effect(() => {
		if (!isRunning || currentStep >= steps.length) return;

		const delay = 600 + Math.random() * 1400;

		const timer = setTimeout(() => {
			currentStep++;

			const newProgress = Math.round(((currentStep) / steps.length) * 100);
			progress = Math.min(newProgress, 100);

			if (currentStep >= steps.length) {
				isRunning = false;
				isComplete = true;
				LogInfo('[InstallationPage] Installation complete');
			}
		}, delay);

		return () => clearTimeout(timer);
	});

	// Auto-start installation when page is reached
	isRunning = true;
	LogInfo('[InstallationPage] Starting installation');

	function formatTime(s: number): string {
		const mins = Math.floor(s / 60);
		const secs = s % 60;
		return `${mins}:${secs.toString().padStart(2, '0')}`;
	}

	const currentLabel = $derived(isComplete ? 'Installation completed!' : steps[currentStep] ?? 'Done');

	// Auto-transition to Finish page when installation is done
	$effect(() => {
		if (!isComplete) return;
		document.dispatchEvent(new CustomEvent('go-next'));
	});
</script>

<PageLayout title="Installing AestheticOS">
	<div class="installation">
		<!-- Target disk info -->
		{#if diskData.diskId}
			<div class="disk-info">
				Target: <strong>{diskData.diskId}</strong>
			</div>
		{/if}

		<!-- Progress bar -->
		<div class="progress-container">
			<div class="progress-bar-bg">
				<div
					class="progress-bar-fill"
					style="--progress: {progress}%"
				></div>
			</div>
			<div class="progress-info">
				<span class="progress-percent">{progress}%</span>
				<span class="progress-time">
					{formatTime(elapsedSeconds)}
				</span>
			</div>
		</div>

		<!-- Current step label -->
		<p class="step-label">{currentLabel}</p>
	</div>
</PageLayout>

<style>
	.installation {
		display: flex;
		flex-direction: column;
		align-items: center;
		gap: 16px;
		width: 100%;
	}

	/* ── Progress bar ── */
	.progress-container {
		width: 520px;
		max-width: calc(100vw - 40px);
		display: flex;
		flex-direction: column;
		gap: 6px;
	}

	.progress-bar-bg {
		width: 100%;
		height: 14px;
		background: rgba(255, 255, 255, 0.15);
		border-radius: 999px;
		overflow: hidden;
	}

	.progress-bar-fill {
		height: 100%;
		width: var(--progress);
		background: linear-gradient(90deg, var(--color-primary), #6db3f2);
		border-radius: 999px;
		transition: width 0.5s ease;
	}

	.progress-info {
		display: flex;
		justify-content: space-between;
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
	}

	.progress-percent {
		font-weight: var(--font-weight-700);
		color: var(--color-primary);
	}

	/* ── Step label ── */
	.step-label {
		margin: 0;
		font-size: 1.05rem;
		font-weight: var(--font-weight-600);
		color: var(--color-text);
		min-height: 1.5em;
		transition: opacity 0.2s;
	}

	/* ── Disk info ── */
	.disk-info {
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
	}

	.disk-info strong {
		color: var(--color-text);
	}
</style>
